def set_idioma(codigo: str) -> None:
    global _idioma_atual
    if codigo in TRADUCOES:
        _idioma_atual = codigo
        QSettings("Vicio", "DublaSync").setValue("idioma", codigo)

def get_idioma() -> str:
    return _idioma_atual

def carregar_idioma_salvo() -> str:
    global _idioma_atual
    salvo = QSettings("Vicio", "DublaSync").value("idioma", "pt")
    _idioma_atual = salvo if salvo in TRADUCOES else "pt"
    return _idioma_atual

def tr(chave: str) -> str:
    return TRADUCOES.get(_idioma_atual, {}).get(chave, TRADUCOES["pt"].get(chave, chave))